set role service_role;
select th.assert((select outcome from public.th_c31_outcome where who = 'holder') = 'synced' and (select outcome from public.th_c31_outcome where who = 'contender') = 'removed', 'both committed');
select th.assert((select coalesce(array_agg(a_plaid_transaction_id order by a_plaid_transaction_id), '{}') from public.card_payment_decisions where kind = 'destination_removed_card' and superseded_by is null) = array['c31-posted'], 'the removal saw the posted row the sync had just committed: the record is on its id, not on the pending one');
select th.assert((public.get_card_payment_states('00000000-0000-0000-0000-0000000000aa')->>'fresh')::boolean and (select evaluated_version = input_version from public.card_payment_eval_versions where user_id = '00000000-0000-0000-0000-0000000000aa'), 'fresh after the removal, the last writer');
select th.assert((select (l->>'state') || '/' || (l->>'reason') || '/' || coalesce(l->>'effectCents', 'null') from (select l from jsonb_array_elements(public.get_card_payment_states('00000000-0000-0000-0000-0000000000aa')->'legs') l where (l->>'transactionId')::uuid = (select id from public.transactions where plaid_transaction_id = 'c31-posted')) x(l)) = 'untracked/removed_card/-12000', 'the posted payment carries the preserved destination');
